INSERT INTO "questions" ("id","subject_id","unit_id","prompt","choices","correct_index","explanation","source","difficulty","published","created_by") VALUES
('20000000-0000-0000-0000-000000000001','criminal-law','10000000-0000-0000-0000-000000000001','형법의 시간적 적용범위에 관한 설명으로 옳은 것은?','["범죄 후 법률이 변경되어 형이 가벼워진 경우에도 행위시법만 적용한다.","재판확정 후 법률이 변경되어 그 행위가 범죄를 구성하지 않게 되면 형의 집행을 면제한다.","한시법의 추급효는 언제나 인정된다.","형법 제1조 제2항은 소송법규의 변경에도 당연히 적용된다."]',1,'형법 제1조 제3항에 따라 재판이 확정된 후 법률의 변경으로 그 행위가 범죄를 구성하지 않게 된 때에는 형의 집행을 면제합니다.','형법 제1조','기본',true,'00000000-0000-0000-0000-000000000001'),
('20000000-0000-0000-0000-000000000002','criminal-law','10000000-0000-0000-0000-000000000002','부작위범에 관한 설명으로 가장 적절한 것은?','["보증인지위는 법률에 의해서만 발생한다.","부작위범의 실행행위는 언제나 결과 발생 시점에 종료된다.","진정부작위범은 명령규범을 부작위로 위반하는 범죄이다.","부진정부작위범에는 인과관계가 필요하지 않다."]',2,'진정부작위범은 일정한 행위를 명하는 규범을 부작위로 위반함으로써 성립합니다.','형법총론','보통',true,'00000000-0000-0000-0000-000000000001'),
('20000000-0000-0000-0000-000000000003','criminal-procedure','10000000-0000-0000-0000-000000000003','현행범인 체포에 관한 설명으로 옳은 것은?','["체포영장이 있어야 한다.","누구든지 영장 없이 체포할 수 있다.","검사만 체포할 수 있다.","반드시 긴급체포 요건을 갖추어야 한다."]',1,'형사소송법 제212조에 따라 현행범인은 누구든지 영장 없이 체포할 수 있습니다.','형사소송법 제212조','기본',true,'00000000-0000-0000-0000-000000000001'),
('20000000-0000-0000-0000-000000000004','criminal-procedure','10000000-0000-0000-0000-000000000004','전문법칙에 관한 설명으로 가장 적절한 것은?','["전문증거는 예외 없이 증거능력이 없다.","피고인이 동의하면 전문증거도 증거로 할 수 있다.","탄핵증거에도 전문법칙이 그대로 적용된다.","진술의 임의성과는 무관하다."]',1,'형사소송법 제318조의 증거동의가 있으면 전문증거도 증거로 할 수 있습니다.','형사소송법 제318조','보통',true,'00000000-0000-0000-0000-000000000001'),
('20000000-0000-0000-0000-000000000005','corrections','10000000-0000-0000-0000-000000000005','교정의 이념에 관한 설명으로 가장 적절한 것은?','["응보와 재사회화는 논리적으로 양립할 수 없다.","특별예방은 일반 국민에 대한 위하를 의미한다.","사회복귀 이념은 수형자의 재사회화를 중시한다.","회복적 사법은 피해자의 참여를 배제한다."]',2,'사회복귀 이념은 수형자가 책임 있는 사회 구성원으로 복귀하도록 처우와 교육을 제공하는 데 초점을 둡니다.','교정학개론','기본',true,'00000000-0000-0000-0000-000000000001'),
('20000000-0000-0000-0000-000000000006','corrections','10000000-0000-0000-0000-000000000006','수형자 분류의 목적으로 가장 거리가 먼 것은?','["개별처우 계획 수립","시설 안전 확보","재범 위험 평가","모든 수형자에게 동일한 처우 제공"]',3,'분류는 수형자의 특성과 위험·필요를 파악해 개별화된 처우를 제공하기 위한 것이므로 획일적 처우와 거리가 멉니다.','형의 집행 및 수용자의 처우에 관한 법률','기본',true,'00000000-0000-0000-0000-000000000001')
